function Slide1({ onNext, allowSkip }) {
  const { displayed, progress, done, pause, resume, skip } = useTypewriter(SLIDE1_TEXTS, true);

  const handleContinue = () => {
    if (!done) {
      if (allowSkip) skip();
    } else {
      onNext();
    }
  };

  return (
    <div
      className="screen"
      onMouseDown={pause}
      onMouseUp={resume}
      onMouseLeave={resume}
      onTouchStart={pause}
      onTouchEnd={resume}
    >
      <ProgressBar progress={progress} current={0} />
      <QuoteCard top={148} height={284} />
      <OpeningQuote top={178.28} />
      <p className="slide-text" style={{ top: 256 }} dir="auto">
        {displayed[0]}
        <span className={`typing-cursor ${done ? "cursor-hidden" : "cursor-blink"}`} />
      </p>
      <BgDecor />
      {allowSkip ? (
        <div className="next-btn-wrap" style={{ top: 480 }}>
          <NextButton onClick={handleContinue} label={done ? "המשך !" : "דלג"} />
        </div>
      ) : (
        done && (
          <div className="next-btn-wrap" style={{ top: 480 }}>
            <NextButton onClick={onNext} />
          </div>
        )
      )}
    </div>
  );
}

