// ===== רכיב: נגן אודיו מלא (הפעלה/השהיה, פס גרירה, קפיצה 10 שניות + שליטה במהירות) =====
function AudioPlayer({ src }) {
  const audioRef = useRef(null);

  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackRate, setPlaybackRate] = useState(1);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const updateTime = () => setCurrentTime(audio.currentTime);
    const updateDuration = () => setDuration(audio.duration || 0);
    const onEnded = () => setPlaying(false);

    audio.addEventListener("timeupdate", updateTime);
    audio.addEventListener("loadedmetadata", updateDuration);
    audio.addEventListener("ended", onEnded);

    return () => {
      audio.removeEventListener("timeupdate", updateTime);
      audio.removeEventListener("loadedmetadata", updateDuration);
      audio.removeEventListener("ended", onEnded);
    };
  }, []);

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;

    if (playing) {
      audio.pause();
    } else {
      audio.play().catch(() => {});
    }

    setPlaying((v) => !v);
  };

  const skip = (seconds) => {
    const audio = audioRef.current;
    if (!audio) return;

    const next = Math.min(
      Math.max(audio.currentTime + seconds, 0),
      duration || audio.duration || 0
    );

    audio.currentTime = next;
    setCurrentTime(next);
  };

  const onSeek = (e) => {
    const audio = audioRef.current;
    if (!audio) return;

    const value = Number(e.target.value);
    audio.currentTime = value;
    setCurrentTime(value);
  };

  const changePlaybackRate = (e) => {
    const audio = audioRef.current;
    if (!audio) return;

    const rate = Number(e.target.value);
    audio.playbackRate = rate;
    setPlaybackRate(rate);
  };

  const formatTime = (t) => {
    if (!isFinite(t) || t < 0) return "0:00";

    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);

    return `${m}:${s.toString().padStart(2, "0")}`;
  };

  if (!src) return null;

  return (
    <div className="audio-player" dir="ltr">
      <audio ref={audioRef} src={src} preload="metadata" />

      <div className="audio-player-controls">
        <button
          type="button"
          className="audio-player-skip"
          onClick={() => skip(-10)}
          aria-label="10 שניות אחורה"
        >
          <div className="skip-icon">
            <RotateCcw size={28} strokeWidth={2} />
            <span>10</span>
          </div>
        </button>

        <button
          type="button"
          className="audio-player-play"
          onClick={togglePlay}
          aria-label={playing ? "השהה" : "נגן"}
        >
          {playing ? (
            <Pause size={22} fill="#fff" />
          ) : (
            <Play size={22} fill="#fff" />
          )}
        </button>

        <button
          type="button"
          className="audio-player-skip"
          onClick={() => skip(10)}
          aria-label="10 שניות קדימה"
        >
          <div className="skip-icon">
            <RotateCw size={28} strokeWidth={2} />
            <span>10</span>
          </div>
        </button>
      </div>

      {/* בחירת מהירות */}<div className="audio-player-speed">
  <label className="audio-player-speed-label" htmlFor="speed">
    מהירות
  </label>

  <select
    id="speed"
    className="audio-player-speed-select"
    value={playbackRate}
    onChange={changePlaybackRate}
  >
    <option value={0.75}>0.75×</option>
    <option value={1}>1×</option>
    <option value={1.25}>1.25×</option>
    <option value={1.5}>1.5×</option>
    <option value={2}>2×</option>
  </select>
</div>

      <div className="audio-player-seek-row">
        <span className="audio-player-time">
          {formatTime(currentTime)}
        </span>

        <input
          type="range"
          className="audio-player-range"
          min={0}
          max={duration || 0}
          step={0.1}
          value={currentTime}
          onChange={onSeek}
        />

        <span className="audio-player-time">
          {formatTime(duration)}
        </span>
      </div>
    </div>
  );
}



