// ===== אפליקציה ראשית =====
export default function App() {
  const [screen, setScreen] = useState("intro");
  const [selectedTopicId, setSelectedTopicId] = useState(null);
  const [selectedItemId, setSelectedItemId] = useState(null);
  const [selectedChapterId, setSelectedChapterId] = useState(null);

 

  const selectedTopic = TOPICS.find((t) => t.id === selectedTopicId) || null;
  const selectedItem =
    (selectedTopic && selectedTopic.items.find((it) => it.id === selectedItemId)) || null;
  const selectedChapter =
    (selectedItem &&
      selectedItem.chapters &&
      selectedItem.chapters.find((c) => c.id === selectedChapterId)) ||
    null;

  // האם המשתמש כבר עבר את שני משפטי הפתיחה (סלייד 1+2) בעבר,
  // בביקור קודם? נבדק פעם אחת בכניסה לאפליקציה (לפני שמסמנים
  // את הביקור הנוכחי) - וקובע אם להציג כפתור "דלג" מיידי במסכי
  // הפתיחה, או לדרוש לצפות בהקלדה עד הסוף (כמו בפעם הראשונה).
  const [allowSkipIntro] = useState(() => hasSeenIntroSlides());

  // כניסה למסך הפתיח: תמיד עוברים דרך סלייד 1+2 (על אומרי + על
  // הלומדה מגיעים אחריהם כרגיל). ההבדל בין ביקור ראשון לביקור
  // חוזר הוא רק אם מוצג כפתור "דלג" מיידי (allowSkipIntro).
  const handleIntroStart = () => {
    setScreen("slide1");
  };

  const handleIntroSlidesFinished = () => {
    markIntroSlidesSeen();
    setScreen("about");
  };

  const handleSelectTopic = (topic) => {
    setSelectedTopicId(topic.id);
    setScreen("topicDetail");
  };

  const handleSelectItem = (item) => {
    setSelectedItemId(item.id);
    // תת-נושאים עם type: "chapters" (כרגע: "רוח המפקד") מציגים קודם
    // רשימת פרקים משלהם, ולא ישר את מסך התוכן הרגיל.
    setScreen(item.type === "chapters" ? "spiritChapters" : "item");
  };

  const handleSelectChapter = (chapter) => {
    setSelectedChapterId(chapter.id);
    setScreen("spiritChapter");
  };

  const backToTopics = () => setScreen("topics");
  const backToTopicDetail = () => setScreen("topicDetail");
  const backToSpiritChapters = () => setScreen("spiritChapters");

  let content = null;
  if (screen === "intro") content = <IntroScreen onStart={handleIntroStart} />;
      else if (screen === "slide1")
    content = <Slide1 onNext={() => setScreen("slide2")} allowSkip={allowSkipIntro} />;
  else if (screen === "slide2")
    content = <Slide2 onNext={handleIntroSlidesFinished} allowSkip={allowSkipIntro} />;
  else if (screen === "about") content = <AboutScreen onNext={() => setScreen("curriculum")} />;
  else if (screen === "curriculum") content = <CurriculumScreen onNext={() => setScreen("topics")} />;
  else if (screen === "topics")
    content = <TopicsScreen onAbout={() => setScreen("about")} onSelectTopic={handleSelectTopic} />;
  else if (screen === "topicDetail" && selectedTopic)
    content = (
      <TopicDetailScreen topic={selectedTopic} onBack={backToTopics} onSelectItem={handleSelectItem} />
    );
  else if (screen === "item" && selectedTopic && selectedItem) {
    if (selectedItem.type === "song")
      content = <SongItemScreen topic={selectedTopic} item={selectedItem} onBack={backToTopicDetail} />;
    else if (selectedItem.type === "video")
      content = <VideoItemScreen topic={selectedTopic} item={selectedItem} onBack={backToTopicDetail} />;
    else content = <TextItemScreen topic={selectedTopic} item={selectedItem} onBack={backToTopicDetail} />;
  } else if (screen === "spiritChapters" && selectedTopic && selectedItem) {
    content = (
      <CommandSpiritChaptersScreen
        topic={selectedTopic}
        item={selectedItem}
        onBack={backToTopicDetail}
        onSelectChapter={handleSelectChapter}
      />
    );
  } else if (screen === "spiritChapter" && selectedTopic && selectedItem && selectedChapter) {
    content = (
      <CommandSpiritChapterScreen
        topic={selectedTopic}
        item={selectedItem}
        chapter={selectedChapter}
        onBack={backToSpiritChapters}
      />
    );
  }

  // ===== קביעת תמונת הרקע של המסך הנוכחי (עבור שכבת הרקע במסך המלא) =====
  let currentBg = bgImg;
  if (screen === "topics") currentBg = bgImg;
  else if (
    (screen === "topicDetail" || screen === "item" || screen === "spiritChapters" || screen === "spiritChapter") &&
    selectedTopic
  )
    currentBg = selectedTopic.bgImg;

  return (
    <AppScaleWrapper bgSrc={currentBg}>
      <div className="app-root">{content}</div>
    </AppScaleWrapper>
  );
}